// Cookies posted by the "Connect X" extension (caller already identified by n8n sign-in). One row per X account (keyed by account id).
const b = $json.body || {};
if (!b.auth_token || !b.ct0) throw new Error('Missing auth_token or ct0 - make sure you are logged into x.com');
const acct = decodeURIComponent(String(b.twid || '')).replace(/"/g, '').replace(/^u=/, '');
if (!/^\d+$/.test(acct)) throw new Error('Missing twid cookie - log into x.com and try again');
return [{ json: {
  session_key: acct,
  owner: $json.user_id,
  auth_token: String(b.auth_token),
  ct0: String(b.ct0),
  twid: String(b.twid),
  status: 'connected',
  last_error: '',
  connected_at: new Date().toISOString(),
} }];

// Turns every paginated Bookmarks response into one row per tweet.
// If X rejected the session, emits a single {__status:'expired'} item instead.
const ACCT = $('Current Account').first().json.session_key;
const pages = $input.all().map(i => i.json);
const now = new Date().toISOString();
const rows = new Map();
let expired = null;
let pageCount = 0;

const unwrap = (r) => {
  if (!r) return null;
  if (r.__typename === 'TweetWithVisibilityResults') return r.tweet;
  if (r.__typename === 'TweetTombstone' || r.__typename === 'TweetUnavailable') return null;
  return r;
};

const userOf = (t) => {
  const u = t?.core?.user_results?.result || {};
  return {
    name: u.core?.name ?? u.legacy?.name ?? '',
    handle: u.core?.screen_name ?? u.legacy?.screen_name ?? '',
    avatar: (u.avatar?.image_url ?? u.legacy?.profile_image_url_https ?? '').replace('_normal.', '_bigger.'),
  };
};

const textOf = (t) => {
  let txt = t?.note_tweet?.note_tweet_results?.result?.text ?? t?.legacy?.full_text ?? '';
  // strip trailing t.co media links, expand others
  const urls = [...(t?.legacy?.entities?.urls || []), ...(t?.note_tweet?.note_tweet_results?.result?.entity_set?.urls || [])];
  for (const u of urls) if (u.url && u.expanded_url) txt = txt.split(u.url).join(u.expanded_url);
  for (const m of (t?.legacy?.extended_entities?.media || t?.legacy?.entities?.media || [])) if (m.url) txt = txt.split(m.url).join('');
  return txt.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();
};

const mediaOf = (t) => (t?.legacy?.extended_entities?.media || []).map(m => {
  const out = { type: m.type, thumb: m.media_url_https };
  if (m.video_info?.variants) {
    const mp4 = m.video_info.variants.filter(v => v.content_type === 'video/mp4').sort((a, b) => (b.bitrate || 0) - (a.bitrate || 0))[0];
    if (mp4) out.video = mp4.url;
  }
  return out;
});

for (const p of pages) {
  pageCount++;
  const status = p.statusCode ?? 200;
  const body = typeof p.body === 'string' ? (() => { try { return JSON.parse(p.body); } catch { return {}; } })() : (p.body || {});
  const errs = body.errors || [];
  if (status === 401 || status === 403 || errs.some(e => [32, 89, 239, 353].includes(e.code))) {
    if (rows.size === 0) expired = `X rejected the session (HTTP ${status}${errs[0] ? ': ' + errs[0].message : ''})`;
    break;
  }
  const instructions = body?.data?.bookmark_timeline_v2?.timeline?.instructions || [];
  const entries = instructions.flatMap(i => i.entries || []);
  for (const e of entries) {
    const t = unwrap(e?.content?.itemContent?.tweet_results?.result);
    if (!t?.legacy) continue;
    const id = t.rest_id || t.legacy.id_str;
    if (rows.has(id)) continue;
    const user = userOf(t);
    const q = unwrap(t.quoted_status_result?.result);
    const likes = t.legacy.favorite_count || 0;
    const engagement = likes + (t.legacy.retweet_count || 0) + (t.legacy.reply_count || 0) + (t.legacy.quote_count || 0);
    const data = {
      id, text: textOf(t), name: user.name, handle: user.handle, avatar: user.avatar,
      url: `https://x.com/${user.handle || 'i'}/status/${id}`,
      media: mediaOf(t),
      likes, rts: t.legacy.retweet_count || 0, replies: t.legacy.reply_count || 0,
      views: Number(t.views?.count || 0),
      quote: q?.legacy ? { ...userOf(q), text: textOf(q), url: `https://x.com/${userOf(q).handle || 'i'}/status/${q.rest_id}`, media: mediaOf(q) } : null,
    };
    rows.set(id, {
      tweet_id: id,
      account_id: ACCT,
      sort_index: String(e.sortIndex || ''),
      tweet_created_at: new Date(t.legacy.created_at).toISOString(),
      author_handle: user.handle,
      likes,
      engagement,
      data: JSON.stringify(data),
      synced_at: now,
    });
  }
}

