    if (!bearer && doc.header && doc.header.authorization) bearer = String(doc.header.authorization).replace(/^Bearer\s+/i, '');
  } catch (e) {}
}

if (!mainUrl && !queryId) throw new Error('x.com returned a logged-out page. X Session cookies (auth_token/ct0) are likely expired. Refresh the "X Session" credential.');
if (!queryId || !bearer) throw new Error('Could not discover Bookmarks queryId/bearer from x.com JS.');

const fieldToggles = {};
for (const t of toggleNames) fieldToggles[t] = false;

return [{ json: { queryId, bearer, features: JSON.stringify(features), fieldToggles: JSON.stringify(fieldToggles), source, discovered_at: new Date().toISOString(), logged_in: !!mainUrl } }];

// n8n has already verified the sign-in token (n8n User Auth) before this runs.
// Read the caller's n8n user id from it; no id -> request is refused.
const h = $json.headers || {};
const tok = String(h.authorization || '').replace(/^Bearer\s+/i, '');
let sub = null;
try {
  const part = tok.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
  const txt = typeof Buffer !== 'undefined' ? Buffer.from(part, 'base64').toString('utf8') : atob(part);
  sub = JSON.parse(txt).sub || null;
} catch (e) {}
const b = $json.body || {};
return [{ json: { user_id: sub, action: sub ? String(b.action || '') : 'deny', body: b } }];

// Which X accounts this run syncs: schedule = all; page Sync = the caller's accounts; extension connect = the account just connected.
let rows = $input.all().map(i => i.json).filter(r => r.session_key);
let who = null;
try { who = $('Who Is Calling').first().json; } catch (e) {}
if (who && who.user_id) {
  if (who.action === 'connect') {
    let acct = null;
    try { acct = $('Build Session Row').first().json.session_key; } catch (e) {}
    rows = rows.filter(r => r.session_key === acct);
  } else {
    rows = rows.filter(r => r.owner === who.user_id);
  }
}
return rows.map(json => ({ json }));
